function StepSigningRepository{Section 'Signing repository';$root=SigningRoot;if($root){Log "Existing signing root: $root";$a=Read-Host 'Use this directory? [Y]es / [N]o / [C]ancel';if($a -match '^[Cc]$'){throw 'Operation cancelled.'};if($a -notmatch '^[Yy]$'){$root=$null}};if(-not $root){$admin=[Security.Principal.WindowsPrincipal]::new([Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator);if(-not $admin){throw "Run elevated to persist $($script:Cfg.Env) at Machine scope."};$root=Ask 'Enter signing assets root directory' {param($v)if([string]::IsNullOrWhiteSpace($v)){throw 'Path cannot be empty.'};[IO.Path]::GetFullPath($v)|Out-Null;return $true};$root=[IO.Path]::GetFullPath($root);EnsureDir $root;[Environment]::SetEnvironmentVariable($script:Cfg.Env,$root,'Machine');[Environment]::SetEnvironmentVariable($script:Cfg.Env,$root,'Process')};$script:Ctx.Paths=Paths $root;foreach($d in @($script:Ctx.Paths.App,$script:Ctx.Paths.KeystoreDir,$script:Ctx.Paths.MetadataDir,$script:Ctx.Paths.BackupDir,$script:Ctx.Paths.ReleasesDir)){EnsureDir $d};Log "Signing repository: $($script:Ctx.Paths.App)" Success}
